SELECT e.emp_id, e.emp_name, d.dept_name
FROM emp e JOIN dept d ON e.dept_id = d.dept_id
ORDER BY e.emp_id;

SELECT emp_id, salary FROM emp
WHERE salary BETWEEN 3000 AND 4000
ORDER BY emp_id;

SELECT emp_id, bonus FROM emp
WHERE bonus <> 0 OR bonus IS NULL
ORDER BY emp_id;

SELECT emp_id, bonus FROM emp
ORDER BY CASE WHEN bonus IS NULL THEN 1 ELSE 0 END,
         bonus, emp_id;

SELECT dept_id, COUNT(*) AS people
FROM emp JOIN dept USING (dept_id)
GROUP BY dept_id ORDER BY dept_id;

SELECT d.dept_id, e.emp_id
FROM dept d LEFT JOIN emp e ON d.dept_id = e.dept_id
ORDER BY d.dept_id, e.emp_id;

SELECT emp_id, salary FROM emp
WHERE dept_id IN (SELECT dept_id FROM emp WHERE salary >= 4000)
ORDER BY emp_id;

SELECT c.customer_id FROM customer c
WHERE EXISTS (
  SELECT 1 FROM orders o
  WHERE o.customer_id = c.customer_id AND o.status = 'PAID'
)
ORDER BY c.customer_id;

SELECT d.dept_id FROM dept d
WHERE NOT EXISTS (
  SELECT 1 FROM emp e WHERE e.dept_id = d.dept_id
)
ORDER BY d.dept_id;

SELECT val FROM (
  SELECT val FROM set_a
  UNION
  SELECT val FROM set_b
) u
ORDER BY CASE WHEN val IS NULL THEN 1 ELSE 0 END, val;

SELECT emp_id, dept_id, salary,
       SUM(salary) OVER (PARTITION BY dept_id) AS dept_total
FROM emp ORDER BY emp_id;

SELECT TOP (3) emp_id, salary
FROM emp
ORDER BY salary DESC, emp_id;

SELECT e.emp_id, e.emp_name, m.emp_name AS manager_name
FROM emp e LEFT JOIN emp m ON e.manager_id = m.emp_id
ORDER BY e.emp_id;

SELECT dept_id, quarter, amount
FROM quarterly
UNPIVOT (
  amount FOR quarter IN (q1 AS 'Q1', q2 AS 'Q2')
)
ORDER BY dept_id, quarter;

SELECT code FROM code_sample
WHERE REGEXP_LIKE(code, '^[A-Z]{2}[0-9]{3}$', 'c')
ORDER BY code;

UPDATE lab_account SET balance = balance - 10 WHERE account_id = 1;
SAVEPOINT sp1;
UPDATE lab_account SET balance = balance - 20 WHERE account_id = 1;
ROLLBACK TO sp1;
COMMIT;
SELECT balance FROM lab_account WHERE account_id = 1;

